macro_rules! deps {
    () => {
        Number!();
        Limb!();
    };
}

macro_rules! large {
    () => {
        deps!();
        mod large { use super :: * ; # [doc = " Compare `x` to `y`, in little-endian order."] # [inline] pub fn compare (x : & [Limb] , y : & [Limb]) -> cmp :: Ordering { if x . len () > y . len () { cmp :: Ordering :: Greater } else if x . len () < y . len () { cmp :: Ordering :: Less } else { let iter = x . iter () . rev () . zip (y . iter () . rev ()) ; for (& xi , & yi) in iter { if xi > yi { return cmp :: Ordering :: Greater ; } else if xi < yi { return cmp :: Ordering :: Less ; } } cmp :: Ordering :: Equal } } # [doc = " Check if x is less than y."] # [inline] pub fn less (x : & [Limb] , y : & [Limb]) -> bool { compare (x , y) == cmp :: Ordering :: Less } # [doc = " Check if x is greater than or equal to y."] # [inline] pub fn greater_equal (x : & [Limb] , y : & [Limb]) -> bool { ! less (x , y) } # [doc = " Implied AddAssign implementation for bigints."] # [doc = ""] # [doc = " Allows us to choose a start-index in x to store, so we can avoid"] # [doc = " padding the buffer with zeros when not needed, optimized for vectors."] pub fn iadd_impl (x : & mut Vec < Limb > , y : & [Limb] , xstart : usize) { if y . len () > x . len () - xstart { x . resize (y . len () + xstart , 0) ; } let mut carry = false ; for (xi , yi) in x [xstart ..] . iter_mut () . zip (y . iter ()) { let mut tmp = scalar :: iadd (xi , * yi) ; if carry { tmp |= scalar :: iadd (xi , 1) ; } carry = tmp ; } if carry { small :: iadd_impl (x , 1 , y . len () + xstart) ; } } # [doc = " AddAssign bigint to bigint."] # [inline] pub fn iadd (x : & mut Vec < Limb > , y : & [Limb]) { iadd_impl (x , y , 0) ; } # [doc = " Add bigint to bigint."] # [inline] pub fn add (x : & [Limb] , y : & [Limb]) -> Vec < Limb > { let mut z = Vec :: < Limb > :: default () ; z . extend_from_slice (x) ; iadd (& mut z , y) ; z } # [doc = " SubAssign bigint to bigint."] pub fn isub (x : & mut Vec < Limb > , y : & [Limb]) { debug_assert ! (greater_equal (x , y)) ; let mut carry = false ; for (xi , yi) in x . iter_mut () . zip (y . iter ()) { let mut tmp = scalar :: isub (xi , * yi) ; if carry { tmp |= scalar :: isub (xi , 1) ; } carry = tmp ; } if carry { small :: isub_impl (x , 1 , y . len ()) ; } else { small :: normalize (x) ; } } # [doc = " Number of digits to bottom-out to asymptotically slow algorithms."] # [doc = ""] # [doc = " Karatsuba tends to out-perform long-multiplication at ~320-640 bits,"] # [doc = " so we go halfway, while Newton division tends to out-perform"] # [doc = " Algorithm D at ~1024 bits. We can toggle this for optimal performance."] pub const KARATSUBA_CUTOFF : usize = 32 ; # [doc = " Grade-school multiplication algorithm."] # [doc = ""] # [doc = " Slow, naive algorithm, using limb-bit bases and just shifting left for"] # [doc = " each iteration. This could be optimized with numerous other algorithms,"] # [doc = " but it's extremely simple, and works in O(n*m) time, which is fine"] # [doc = " by me. Each iteration, of which there are `m` iterations, requires"] # [doc = " `n` multiplications, and `n` additions, or grade-school multiplication."] fn long_mul (x : & [Limb] , y : & [Limb]) -> Vec < Limb > { let mut z : Vec < Limb > = small :: mul (x , y [0]) ; z . resize (x . len () + y . len () , 0) ; for (i , & yi) in y [1 ..] . iter () . enumerate () { let zi : Vec < Limb > = small :: mul (x , yi) ; iadd_impl (& mut z , & zi , i + 1) ; } small :: normalize (& mut z) ; z } # [doc = " Split two buffers into halfway, into (lo, hi)."] # [inline] pub fn karatsuba_split (z : & [Limb] , m : usize) -> (& [Limb] , & [Limb]) { (& z [.. m] , & z [m ..]) } # [doc = " Karatsuba multiplication algorithm with roughly equal input sizes."] # [doc = ""] # [doc = " Assumes `y.len() >= x.len()`."] fn karatsuba_mul (x : & [Limb] , y : & [Limb]) -> Vec < Limb > { if y . len () <= KARATSUBA_CUTOFF { long_mul (x , y) } else if x . len () < y . len () / 2 { karatsuba_uneven_mul (x , y) } else { let m = y . len () / 2 ; let (xl , xh) = karatsuba_split (x , m) ; let (yl , yh) = karatsuba_split (y , m) ; let sumx = add (xl , xh) ; let sumy = add (yl , yh) ; let z0 = karatsuba_mul (xl , yl) ; let mut z1 = karatsuba_mul (& sumx , & sumy) ; let z2 = karatsuba_mul (xh , yh) ; isub (& mut z1 , & z2) ; isub (& mut z1 , & z0) ; let len = z0 . len () . max (m + z1 . len ()) . max (2 * m + z2 . len ()) ; let mut result = z0 ; result . reserve_exact (len - result . len ()) ; iadd_impl (& mut result , & z1 , m) ; iadd_impl (& mut result , & z2 , 2 * m) ; result } } # [doc = " Karatsuba multiplication algorithm where y is substantially larger than x."] # [doc = ""] # [doc = " Assumes `y.len() >= x.len()`."] fn karatsuba_uneven_mul (x : & [Limb] , mut y : & [Limb]) -> Vec < Limb > { let mut result = Vec :: < Limb > :: default () ; result . resize (x . len () + y . len () , 0) ; let mut start = 0 ; while ! y . is_empty () { let m = x . len () . min (y . len ()) ; let (yl , yh) = karatsuba_split (y , m) ; let prod = karatsuba_mul (x , yl) ; iadd_impl (& mut result , & prod , start) ; y = yh ; start += m ; } small :: normalize (& mut result) ; result } # [doc = " Forwarder to the proper Karatsuba algorithm."] # [inline] fn karatsuba_mul_fwd (x : & [Limb] , y : & [Limb]) -> Vec < Limb > { if x . len () < y . len () { karatsuba_mul (x , y) } else { karatsuba_mul (y , x) } } # [doc = " MulAssign bigint to bigint."] # [inline] pub fn imul (x : & mut Vec < Limb > , y : & [Limb]) { if y . len () == 1 { small :: imul (x , y [0]) ; } else { * x = karatsuba_mul_fwd (x , y) ; } } }
    };
}

large!()